    private static DefaultTableModel model(String...columns){return new DefaultTableModel(columns,0){@Override public boolean isCellEditable(int r,int c){return false;}};}
    private JButton button(String label,Runnable action){JButton b=new JButton(label);b.addActionListener(e->{if(!working)try{action.run();}catch(Exception ex){error(ex);}});return b;}
    private JButton action(String label,String permission,Runnable run){JButton b=button(label,run);buttons.put(label,b);b.putClientProperty("permission",permission);return b;}
    private static JsonObject request(String action){JsonObject b=new JsonObject();b.addProperty("action",action);return b;}
    private void refresh(){JsonObject b=request("LIST");b.addProperty("search",search.getText());b.addProperty("filter",filter.getSelectedItem().toString());call(b,data->{permissions=permissions(data);ordersModel.setRowCount(0);rows.clear();for(JsonElement e:data.getAsJsonArray("rows")){JsonObject r=e.getAsJsonObject();rows.add(r);ordersModel.addRow(new Object[]{s(r,"number"),s(r,"customerName"),s(r,"customerPhone"),trackingLabel(s(r,"tracking")),s(r,"total"),s(r,"paid"),s(r,"balance")});}controls();});}
    private void fresh(){if(!confirmDiscard())return;order=null;detail=null;customerId=null;name.setText("");phone.setText("");expected.setText("");shipping.setText("0");notes.setText("");summary.setText("New draft · Deckers "+managers.SessionManager.getCurrentLocationName()+" · save before attaching screenshots");history.setText("");lineValues.clear();renderLines();savedDraft=draft().deepCopy();controls();}
    private void controls(){for(JButton b:buttons.values())b.setEnabled(!working&&permissions.contains("OVERSEAS_ORDERS_"+b.getClientProperty("permission")));boolean edit=permissions.contains("OVERSEAS_ORDERS_QUOTE")&&!working;for(JTextField f:List.of(name,phone,expected,shipping))f.setEditable(edit);notes.setEditable(edit);}
    private void showDetail(JsonObject data){detail=data;order=data.getAsJsonObject("order");permissions=permissions(data);customerId=!order.has("customer_id")||order.get("customer_id").isJsonNull()?null:order.get("customer_id").getAsInt();name.setText(s(order,"customer_name"));phone.setText(s(order,"customer_phone"));expected.setText(s(order,"expected_date"));shipping.setText(s(order,"shipping"));notes.setText(s(order,"notes"));summary.setText(s(order,"number")+" · Deckers "+s(order,"store_name")+" · "+s(order,"state")+" · Paid GYD "+s(order,"paid")+" · Balance GYD "+s(order,"balance"));lineValues.clear();for(JsonElement e:order.getAsJsonArray("lines"))lineValues.add(e.getAsJsonObject().deepCopy());StringBuilder h=new StringBuilder();for(JsonElement e:data.getAsJsonArray("payments")){JsonObject p=e.getAsJsonObject();h.append(s(p,"created_at")).append(" · ").append(s(p,"payment_action")).append(" GYD ").append(s(p,"payment_amount")).append(" · ").append(s(p,"payment_method")).append(" · ").append(s(p,"taken_by_name")).append('\n');}for(JsonElement e:data.getAsJsonArray("events")){JsonObject v=e.getAsJsonObject();h.append(s(v,"at")).append(" · ").append(s(v,"action")).append(" · ").append(s(v,"actor")).append(" · ").append(s(v,"reason")).append('\n');}history.setText(h.toString());renderLines();savedDraft=draft().deepCopy();controls();}
    private void renderLines(){itemsModel.setRowCount(0);BigDecimal total=BigDecimal.ZERO;for(JsonObject l:lineValues){BigDecimal subtotal=l.get("unit_price").getAsBigDecimal().multiply(l.get("quantity").getAsBigDecimal());total=total.add(subtotal);itemsModel.addRow(new Object[]{s(l,"description"),s(l,"seller"),trackingLabel(s(l,"tracking")),s(l,"options"),s(l,"quantity"),s(l,"unit_price"),subtotal,s(l,"purchased"),s(l,"shipped"),s(l,"arrived"),s(l,"collected"),s(l,"screenshot").isBlank()?"":"Attached"});}try{total=total.add(new BigDecimal(shipping.getText().isBlank()?"0":shipping.getText().trim()));}catch(Exception ignored){}totals.setText("Quoted total GYD "+total.toPlainString());}
    private JsonObject draft(){JsonObject o=new JsonObject();o.addProperty("customer_name",name.getText());o.addProperty("customer_phone",phone.getText());o.addProperty("customer_id",customerId);o.addProperty("expected_date",expected.getText());o.addProperty("shipping",new BigDecimal(shipping.getText().isBlank()?"0":shipping.getText().trim()));o.addProperty("notes",notes.getText());JsonArray l=new JsonArray();lineValues.forEach(l::add);o.add("lines",l);return o;}
    private void issue(){
        if(order==null||!"DRAFT".equals(s(order,"state")))throw new IllegalArgumentException("Select a saved draft to issue.");
        JsonObject b=request("SAVE");b.addProperty("requestId",UUID.randomUUID().toString());b.add("id",order.get("overseas_order_id"));b.add("revision",order.get("revision"));b.add("order",draft());
        call(b,data->{showDetail(data);change("ISSUE",new JsonObject(),false);});
    }
    private void save(){JsonObject b=new JsonObject();b.add("order",draft());if(order!=null&&order.has("custom_order_id")&&!order.get("custom_order_id").isJsonNull()&&(order.get("paid").getAsBigDecimal().signum()>0||lineValues.stream().anyMatch(l->l.has("purchased")&&l.get("purchased").getAsInt()>0))){JsonObject reason=reason();if(reason==null)return;b=with(b,reason);}change("SAVE",b,false);}
    private static JsonObject with(JsonObject b,JsonObject extra){for(var e:extra.entrySet())b.add(e.getKey(),e.getValue());return b;}
    private void change(String action,JsonObject b,boolean printPayment){if(b==null)return;if(!Set.of("SAVE","ISSUE","UPLOAD").contains(action))requireSaved();b.addProperty("action",action);b.addProperty("requestId",UUID.randomUUID().toString());if(order!=null){b.add("id",order.get("overseas_order_id"));b.add("revision",order.get("revision"));}else if(!action.equals("SAVE"))throw new IllegalArgumentException("Save the draft first.");call(b,data->{showDetail(data);if(printPayment)printLatest();});}
    private JsonObject reason(){String value=JOptionPane.showInputDialog(this,"Reason for this adjustment / cancellation:");if(value==null)return null;if(value.isBlank())throw new IllegalArgumentException("A reason is required.");JsonObject b=new JsonObject();b.addProperty("reason",value);return b;}
    private void lookupPhone(){
        String query=phone.getText().trim();long version=++phoneVersion;
        if(!permissions.contains("OVERSEAS_ORDERS_QUOTE")||query.isBlank())return;
        try{utils.CustomerPhoneNumber.normalize(query);}catch(IllegalArgumentException e){return;}
        JsonObject request=request("CUSTOMER_PHONE");request.addProperty("phone",query);
        new SwingWorker<JsonObject,Void>(){
            protected JsonObject doInBackground()throws Exception{return transport.send(request);}
            protected void done(){if(version!=phoneVersion||!query.equals(phone.getText().trim()))return;
                try{JsonObject result=get();phoneMatches.removeAll();for(JsonElement element:result.getAsJsonArray("customers")){JsonObject c=element.getAsJsonObject();int id=c.get("customerId").getAsInt();if(customerId!=null&&customerId==id)continue;
                    if(!c.get("active").getAsBoolean()){phoneMatches.add(new JLabel(c.get("name").getAsString()+" — inactive account; ask an administrator."));continue;}
                    JButton choose=new JButton("Select existing customer: "+c.get("name").getAsString()+" · "+c.get("accountNumber").getAsString());choose.addActionListener(e->{if(version!=phoneVersion)return;customerId=id;name.setText(s(c,"name"));phone.setText(s(c,"phone"));phoneMatches.removeAll();phoneMatches.revalidate();phoneMatches.repaint();});phoneMatches.add(choose);
                }if(result.get("reserved").getAsBoolean()&&result.getAsJsonArray("customers").isEmpty())phoneMatches.add(new JLabel("Number reserved. Ask an administrator to check the customer account."));phoneMatches.revalidate();phoneMatches.repaint();
                }catch(Exception e){phoneMatches.add(new JLabel("Phone lookup unavailable. Use Find customer or retry."));phoneMatches.revalidate();}
            }
        }.execute();
    }    private void findCustomer(){String q=JOptionPane.showInputDialog(this,"Customer name, phone or account number:",phone.getText());if(q==null)return;JsonObject b=request("CUSTOMERS");b.addProperty("search",q);call(b,data->{List<JsonObject> customers=new ArrayList<>();List<String> labels=new ArrayList<>();for(JsonElement e:data.getAsJsonArray("customers")){JsonObject c=e.getAsJsonObject();customers.add(c);labels.add(s(c,"name")+" · "+s(c,"phone")+" · "+s(c,"accountNumber"));}if(labels.isEmpty()){JOptionPane.showMessageDialog(this,"No customers found. Leave the customer unselected to create a new account on issue.");return;}Object choice=JOptionPane.showInputDialog(this,"Select customer","Customer",JOptionPane.PLAIN_MESSAGE,null,labels.toArray(),labels.get(0));if(choice!=null){JsonObject c=customers.get(labels.indexOf(choice));customerId=c.get("customerId").getAsInt();name.setText(s(c,"name"));phone.setText(s(c,"phone"));}});}
    private void editLine(int index){JsonObject old=index>=0?lineValues.get(index):new JsonObject();JPanel form=new JPanel(new GridLayout(0,2,8,8));Map<String,JTextField> fields=new LinkedHashMap<>();String[][] definitions={{"description","Item description"},{"seller","Seller (type a new name or choose a saved seller)"},{"product_url","Product link"},{"options","Size / colour / options"},{"quantity","Quantity"},{"unit_price","Price each GYD (shipping included)"},{"usd_cost","USD cost each (optional)"},{"exchange_rate","Exchange rate (reference only)"}};for(String[] d:definitions){JTextField f=new JTextField(s(old,d[0]),30);if(index<0&&(d[0].equals("quantity")||d[0].equals("unit_price")))f.setText(d[0].equals("quantity")?"1":"0");fields.put(d[0],f);form.add(new JLabel(d[1]));if(d[0].equals("seller")){JComboBox<String> choices=new JComboBox<>();choices.setEditable(true);choices.setEditor(new javax.swing.plaf.basic.BasicComboBoxEditor(){public Component getEditorComponent(){return f;}public Object getItem(){return f.getText();}public void setItem(Object value){f.setText(value==null?"":value.toString());}});form.add(choices);new SwingWorker<JsonObject,Void>(){protected JsonObject doInBackground()throws Exception{return transport.send(request("SELLERS"));}protected void done(){try{String typed=f.getText();for(JsonElement seller:get().getAsJsonArray("sellers"))choices.addItem(seller.getAsString());f.setText(typed);}catch(Exception ignored){}}}.execute();}else form.add(f);}if(JOptionPane.showConfirmDialog(this,form,index<0?"Add overseas item":"Edit overseas item",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;JsonObject l=old.deepCopy();fields.forEach((key,f)->{if(Set.of("unit_price","usd_cost","exchange_rate").contains(key)){if(f.getText().isBlank())l.add(key,JsonNull.INSTANCE);else l.addProperty(key,new BigDecimal(f.getText()));}else if(key.equals("quantity"))l.addProperty(key,Integer.parseInt(f.getText()));else l.addProperty(key,f.getText());});if(index<0)lineValues.add(l);else lineValues.set(index,l);renderLines();int chosen=index<0?lineValues.size()-1:index;items.setRowSelectionInterval(chosen,chosen);Object option=JOptionPane.showInputDialog(this,"Screenshot","Item saved in editor",JOptionPane.PLAIN_MESSAGE,null,new String[]{"Keep current / none","Upload image","Paste clipboard image"},"Keep current / none");if(option!=null&&!option.equals("Keep current / none"))attach(chosen,option.equals("Paste clipboard image"));}
    private void removeLine(){int i=items.getSelectedRow();if(i>=0){lineValues.remove(i);renderLines();}}
    private void attach(int index,boolean clipboard){if(order==null)throw new IllegalArgumentException("Save this draft first, then edit the item to attach a screenshot.");try{byte[] bytes;if(clipboard){Image image=(Image)Toolkit.getDefaultToolkit().getSystemClipboard().getData(DataFlavor.imageFlavor);BufferedImage out=new BufferedImage(image.getWidth(null),image.getHeight(null),BufferedImage.TYPE_INT_RGB);Graphics2D g=out.createGraphics();g.drawImage(image,0,0,null);g.dispose();ByteArrayOutputStream buffer=new ByteArrayOutputStream();javax.imageio.ImageIO.write(out,"png",buffer);bytes=buffer.toByteArray();}else{JFileChooser chooser=new JFileChooser();chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("PNG or JPEG screenshot","png","jpg","jpeg"));if(chooser.showOpenDialog(this)!=JFileChooser.APPROVE_OPTION)return;if(Files.size(chooser.getSelectedFile().toPath())>2000000)throw new IllegalArgumentException("Screenshot must be under 2 MB.");bytes=Files.readAllBytes(chooser.getSelectedFile().toPath());}if(bytes.length>2000000)throw new IllegalArgumentException("Screenshot must be under 2 MB.");JsonObject b=request("UPLOAD");b.add("id",order.get("overseas_order_id"));b.add("revision",order.get("revision"));b.addProperty("requestId",UUID.randomUUID().toString());b.addProperty("base64",Base64.getEncoder().encodeToString(bytes));JsonObject target=lineValues.get(index);call(b,result->{target.add("screenshot",result.get("reference"));renderLines();JOptionPane.showMessageDialog(this,"Screenshot attached in editor. Save quote to keep it on this item.");});}catch(Exception e){error(e);}}
    private void openProductLink(){requireSaved();int i=items.getSelectedRow();if(i<0)throw new IllegalArgumentException("Select an item first.");String link=s(lineValues.get(i),"product_url");if(link.isBlank())throw new IllegalArgumentException("This item has no product link.");try{Desktop.getDesktop().browse(java.net.URI.create(link));}catch(Exception e){error(e);}}    private void preview(){int i=items.getSelectedRow();if(i<0)return;String ref=s(lineValues.get(i),"screenshot");if(ref.isBlank())return;JsonObject b=request("IMAGE");b.add("id",order.get("overseas_order_id"));b.addProperty("reference",ref);call(b,result->{byte[] bytes=Base64.getDecoder().decode(result.get("data").getAsString().split(",",2)[1]);ImageIcon icon=new ImageIcon(bytes);Image scaled=icon.getImage().getScaledInstance(Math.min(700,icon.getIconWidth()),-1,Image.SCALE_SMOOTH);JOptionPane.showMessageDialog(this,new JScrollPane(new JLabel(new ImageIcon(scaled))),"Item screenshot",JOptionPane.PLAIN_MESSAGE);});}
    private JsonObject paymentFields(boolean refund){JPanel p=new JPanel(new GridLayout(0,2,8,8));JTextField amount=new JTextField(),reference=new JTextField();JComboBox<String> method=new JComboBox<>(new String[]{"CASH","CARD","CHEQUE","MMG"});p.add(new JLabel("Amount GYD"));p.add(amount);p.add(new JLabel("Payment method"));p.add(method);p.add(new JLabel("Reference (card / cheque / MMG)"));p.add(reference);if(JOptionPane.showConfirmDialog(this,p,refund?"Refund payment":"Collect payment",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return null;JsonObject b=new JsonObject();b.addProperty("amount",new BigDecimal(amount.getText()));b.addProperty("method",method.getSelectedItem().toString());b.addProperty("reference",reference.getText());return b;}
    private void payment(boolean refund,boolean unused){requireSaved();JsonObject b=paymentFields(refund);if(b==null)return;if(refund){JsonObject r=reason();if(r==null)return;with(b,r);}change(refund?"REFUND":"PAYMENT",b,true);}
    private String trackingLabel(String stage){return switch(stage){case "WAITING_FOR_PAYMENT"->"Waiting for payment";case "PROCESSING"->"Processing";case "ORDERED"->"Ordered";case "PARTIALLY_ORDERED"->"Partially ordered";case "ARRIVED"->"Arrived at Deckers "+(order==null?managers.SessionManager.getCurrentLocationName():s(order,"store_name"));case "PARTIALLY_ARRIVED"->"Partially arrived";case "COLLECTED"->"Collected";default->stage;};}
    private void track(String stage){requireSaved();int index=items.getSelectedRow();if(index<0)throw new IllegalArgumentException("Select an item first.");JsonObject line=lineValues.get(index);JsonObject b=new JsonObject();b.addProperty("stage",stage);JsonArray ids=new JsonArray();ids.add(line.get("line_id"));b.add("lineIds",ids);change("TRACK",b,false);}    private void quantities(boolean collect){requireSaved();if(order==null)throw new IllegalArgumentException("Select an issued order.");DefaultTableModel m=new DefaultTableModel(collect?new String[]{"Item","Ordered","Arrived","Collected total"}:new String[]{"Item","Ordered","Purchased total","Shipped total","Arrived total"},0){@Override public boolean isCellEditable(int r,int col){return col>=(collect?3:2);}};for(JsonObject l:lineValues)m.addRow(collect?new Object[]{s(l,"description"),s(l,"quantity"),s(l,"arrived"),s(l,"collected")}:new Object[]{s(l,"description"),s(l,"quantity"),s(l,"purchased"),s(l,"shipped"),s(l,"arrived")});JTable table=new JTable(m);JPanel panel=new JPanel(new BorderLayout());panel.add(new JLabel(collect?"Enter cumulative collected quantities. Final collection requires full payment.":"Enter cumulative quantities for purchased, shipped and arrived."),BorderLayout.NORTH);panel.add(new JScrollPane(table));if(JOptionPane.showConfirmDialog(this,panel,collect?"Customer collection":"Shipment progress",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;if(table.isEditing())table.getCellEditor().stopCellEditing();JsonArray updates=new JsonArray();for(int i=0;i<m.getRowCount();i++){JsonObject l=new JsonObject();l.add("line_id",lineValues.get(i).get("line_id"));if(!l.has("line_id"))throw new IllegalArgumentException("Save the quote before updating quantities.");String[] keys=collect?new String[]{"collected"}:new String[]{"purchased","shipped","arrived"};for(int j=0;j<keys.length;j++)l.addProperty(keys[j],Integer.parseInt(m.getValueAt(i,(collect?3:2)+j).toString()));updates.add(l);}JsonObject b=new JsonObject();b.add("lines",updates);if(collect&&permissions.contains("OVERSEAS_ORDERS_PAYMENT")&&JOptionPane.showConfirmDialog(this,"Record a payment together with this collection?","Collection payment",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){JsonObject payment=paymentFields(false);if(payment==null)return;with(b,payment);}if(permissions.contains("OVERSEAS_ORDERS_ADJUST")){String reason=JOptionPane.showInputDialog(this,"Reason (required if reducing quantities):","");if(reason==null)return;b.addProperty("reason",reason);}change(collect?"COLLECT":"SHIPMENT",b,collect&&b.has("amount"));}
    private void print(){requireSaved();if(detail==null)throw new IllegalArgumentException("Select a saved order.");List<String> labels=new ArrayList<>();List<JsonObject> receipts=new ArrayList<>();labels.add("Order slip");receipts.add(null);for(JsonElement e:detail.getAsJsonArray("payments")){JsonObject p=e.getAsJsonObject();labels.add(s(p,"payment_action")+" #"+s(p,"custom_order_payment_id")+" · GYD "+s(p,"payment_amount"));receipts.add(p);}Object choice=JOptionPane.showInputDialog(this,"Print document","Overseas order",JOptionPane.PLAIN_MESSAGE,null,labels.toArray(),labels.get(0));if(choice!=null)printDocument(receipts.get(labels.indexOf(choice)));}
    private void printLatest(){JsonArray p=detail.getAsJsonArray("payments");if(p.isEmpty())return;JsonObject receipt=p.get(p.size()-1).getAsJsonObject();boolean first=p.size()==1&&s(receipt,"payment_action").equals("PAYMENT");JsonObject snapshot=detail.deepCopy();new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{if(first)Receipt.CustomOrderSlipPrinter.print(Receipt.OverseasOrderDocuments.build(snapshot,null));Receipt.CustomOrderSlipPrinter.print(Receipt.OverseasOrderDocuments.build(snapshot,receipt));return null;}protected void done(){try{get();}catch(Exception e){JOptionPane.showMessageDialog(OverseasOrders.this,"Payment saved. Printing failed; use Print slip / receipt to retry.\n"+e.getMessage());}}}.execute();}
    private void printDocument(JsonObject receipt){JsonObject snapshot=detail.deepCopy();new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{Receipt.CustomOrderSlipPrinter.print(Receipt.OverseasOrderDocuments.build(snapshot,receipt));return null;}protected void done(){try{get();}catch(Exception e){error(e);}}}.execute();}
    private void call(JsonObject b,Consumer<JsonObject> complete){working=true;controls();setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));new SwingWorker<JsonObject,Void>(){protected JsonObject doInBackground()throws Exception{return transport.send(b);}protected void done(){working=false;setCursor(Cursor.getDefaultCursor());try{complete.accept(get());}catch(Exception e){error(e);}finally{controls();}}}.execute();}
    private boolean dirty(){try{return savedDraft!=null&&!savedDraft.equals(draft());}catch(Exception e){return true;}}
    private boolean confirmDiscard(){return !dirty()||JOptionPane.showConfirmDialog(this,"Discard unsaved quote changes?","Unsaved quote",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
    private void requireSaved(){if(dirty())throw new IllegalArgumentException("Save the quote changes before recording payments, shipment, collection or printing.");}    private void error(Exception e){Throwable root=e;while(root.getCause()!=null)root=root.getCause();JOptionPane.showMessageDialog(this,root.getMessage(),"Overseas Orders",JOptionPane.WARNING_MESSAGE);}
    private static String s(JsonObject o,String key){return !o.has(key)||o.get(key).isJsonNull()?"":o.get(key).getAsString();}
    private static Set<String> permissions(JsonObject data){Set<String> out=new HashSet<>();for(JsonElement p:data.getAsJsonArray("permissions"))out.add(p.getAsString());return Set.copyOf(out);}
